#!/usr/bin/env Rscript

# Title: Figure 3 - Immune-profile PCA by cancer type
#
# Inputs:
#   - data/pca_inputs.rds
#     generated by notebooks/15_PCA_imputation_associations.ipynb
#   - Palettes and themes from R/functions/color_schemes.R and ggplot2_theme.R
# Outputs:
#   - plots/Figure3.pdf, .png and .svg
#   - tables/Figure3_points.csv and Figure3_verification_checks.csv
# Usage (from the repository root):
#   Use the bundled notebook-15 outputs, or rerun notebook 15 to rebuild them.
#   Rscript R/Figure3.R [project_root] [plots_dir]
# This script reads the prepared PCA reference and scores; it does not refit PCA
# or recompute imputation.
#
# Original observations are complete cases projected onto the missMDA reference.
# The cohorts overlap: every Original observation also belongs to missMDA.
# All observations are shown without patient connections. Colours indicate the
# recorded exposure; the plot does not establish a causal treatment effect.

# --- Setup --------------------------------------------------------------------

suppressPackageStartupMessages({
  library(ggplot2)
  library(grid)
})

# --- Data preparation and plotting --------------------------------------------

build_figure3 <- function(project_root, plots_dir = file.path(project_root, "plots"),
                          inputs = NULL, export = TRUE,
                          tables_dir = file.path(project_root, "tables")) {
  source(file.path(project_root, "R/functions", "color_schemes.R"), local = TRUE)
  source(file.path(project_root, "R/functions", "ggplot2_theme.R"), local = TRUE)
  if (is.null(inputs)) {
    source(file.path(project_root, "R/functions", "pca_figure_io.R"), local = TRUE)
    prepared <- read_pca_figure_outputs(project_root, include_statistics = FALSE)
    inputs <- prepared$inputs
  }

  full <- inputs$metadata235
  original <- inputs$real_metadata75
  disease_order <- inputs$disease_order
  therapy_palette <- inputs$therapy_palette
  required_fields <- c("sample_id", "Patient", "cycle", "Disease_type",
                       "exposed_regimen", "PC1", "PC2", "n_missing_original",
                       "any_feature_imputed")
  stopifnot(all(required_fields %in% names(full)),
            all(required_fields %in% names(original)),
            !anyDuplicated(full$sample_id),
            all(original$sample_id %in% full$sample_id),
            !anyDuplicated(paste(full$Patient, full$cycle)))

  prepare_points <- function(data, cohort) {
    data$Patient <- as.character(data$Patient)
    data$cycle_num <- as.integer(sub("^X", "", data$cycle))
    data$Disease_type <- factor(as.character(data$Disease_type), levels = disease_order)
    data$regimen <- factor(as.character(data$exposed_regimen), levels = names(therapy_palette))
    data$dataset <- factor(cohort, levels = c("Original", "missMDA"))
    stopifnot(!anyNA(data$Disease_type), !anyNA(data$regimen),
              !anyNA(data$cycle_num), all(is.finite(data$PC1)),
              all(is.finite(data$PC2)))
    data
  }
  full <- prepare_points(full, "missMDA")
  original <- prepare_points(original, "Original")

  # Verify that complete cases really use the same reference axes.
  original_projection <- predict(inputs$reference_pca,
                                 newdata = inputs$real_features75)[, 1:2, drop = FALSE]
  projected_rows <- match(original$sample_id, rownames(original_projection))
  reference_rows <- match(full$sample_id, rownames(inputs$reference_pca$x))
  overlap_rows <- match(original$sample_id, full$sample_id)
  coordinate_errors <- c(
    original_projection = max(abs(as.matrix(original[, c("PC1", "PC2")]) -
                                    original_projection[projected_rows, ])),
    reference_scores = max(abs(as.matrix(full[, c("PC1", "PC2")]) -
                                inputs$reference_pca$x[reference_rows, 1:2])),
    overlapping_cohorts = max(abs(as.matrix(original[, c("PC1", "PC2")]) -
                                   as.matrix(full[overlap_rows, c("PC1", "PC2")]))))
  stopifnot(all(is.finite(coordinate_errors)), all(coordinate_errors < 1e-9))

  # --- Figure -----------------------------------------------------------------

  regimen_labels <- c(
    "baseline" = "Baseline", "Vincristine" = "Vincristine",
    "Methotrexate" = "Methotrexate", "Cyclophosphamide" = "Cyclophosphamide",
    "Vincristine/Methotrexate" = "Vincristine / Methotrexate",
    "Vincristine/Cyclophosphamide" = "Vincristine / Cyclophosphamide",
    "Vincristine/Methotrexate/Cyclophosphamide" = "Vincristine / Methotrexate / Cyclophosphamide",
    "No therapy" = "No therapy", "Others" = "Others")
  pad_range <- function(x) {
    limits <- range(x, na.rm = TRUE)
    mean(limits) + c(-0.55, 0.55) * max(diff(limits), 1)
  }

  p <- ggplot() +
    geom_hline(yintercept = 0, linetype = "solid", colour = "gray50", linewidth = 0.3) +
    geom_vline(xintercept = 0, linetype = "solid", colour = "gray50", linewidth = 0.3) +
    geom_point(data = full, aes(PC1, PC2, colour = regimen, shape = dataset),
               size = 1.8, stroke = 0.55, alpha = 0.8) +
    geom_point(data = original, aes(PC1, PC2, colour = regimen, shape = dataset),
               size = 1.8, alpha = 0.8) +
    facet_wrap(~Disease_type, ncol = 4, drop = FALSE) +
    scale_colour_manual(values = therapy_palette, limits = names(therapy_palette),
                        breaks = names(therapy_palette), labels = regimen_labels,
                        drop = FALSE, name = NULL) +
    scale_shape_manual(values = c(Original = 16L, missMDA = 1L),
                       limits = c("Original", "missMDA"), drop = FALSE, name = NULL) +
    guides(colour = guide_legend(nrow = 3, byrow = TRUE, order = 1,
                                override.aes = list(alpha = 1, size = 2.5, shape = 16)),
           shape = guide_legend(nrow = 1, order = 2,
                               override.aes = list(colour = "black", alpha = 1, size = 2.6))) +
    coord_cartesian(xlim = pad_range(full$PC1), ylim = pad_range(full$PC2)) +
    labs(title = "A  Immune-profile PCA by cancer",
         x = sprintf("Inverted Immune Checkpoint axis (PC1 = %.1f%%)", inputs$variance_percent[1]),
         y = sprintf("Diversity axis (PC2 = %.1f%%)", inputs$variance_percent[2])) +
    theme_minimal() + myplot + myaxis +
    theme(axis.text.x = element_text(angle = 0, hjust = 0.5),
          strip.background = element_blank(), strip.text = element_text(size = 13),
          legend.position = "top", legend.box = "vertical",
          legend.key.height = grid::unit(0.30, "cm"),
          legend.key.width = grid::unit(0.55, "cm"),
          legend.spacing.y = grid::unit(0.02, "cm"),
          legend.box.spacing = grid::unit(0.12, "cm"),
          plot.subtitle = element_text(size = 11),
          panel.spacing = grid::unit(0.65, "lines"),
          plot.margin = margin(8, 10, 6, 8))

  # --- Verification -----------------------------------------------------------

  built <- ggplot_build(p)
  checks <- data.frame(
    check = c("All diagnoses present", "Five rows by four columns",
              "All completed observations plotted", "All Original observations plotted",
              "Completed cohort uses open circles", "Original uses filled circles",
              "Only points and axis reference lines", "Reference lines are solid",
              "Shared PCA coordinate checks"),
    passed = c(nrow(built$layout$layout) == length(disease_order),
               max(built$layout$layout$ROW) == 5L && max(built$layout$layout$COL) == 4L,
               nrow(built$data[[3]]) == nrow(full), nrow(built$data[[4]]) == nrow(original),
               all(built$data[[3]]$shape == 1L), all(built$data[[4]]$shape == 16L),
               length(p$layers) == 4L &&
                 inherits(p$layers[[1]]$geom, "GeomHline") &&
                 inherits(p$layers[[2]]$geom, "GeomVline") &&
                 all(vapply(p$layers[3:4], function(layer)
                   inherits(layer$geom, "GeomPoint"), logical(1))),
               all(vapply(built$data[1:2], function(layer)
                 all(layer$linetype %in% c(1, "solid")), logical(1))),
               all(coordinate_errors < 1e-9)))
  stopifnot(all(checks$passed))
  point_data <- rbind(full, original)

  # --- Exports ----------------------------------------------------------------

  if (export) {
    for (package in c("ragg", "svglite")) {
      if (!requireNamespace(package, quietly = TRUE)) stop("Required R package: ", package)
    }
    dir.create(plots_dir, recursive = TRUE, showWarnings = FALSE)
    dir.create(tables_dir, recursive = TRUE, showWarnings = FALSE)
    for (extension in c("pdf", "png", "svg")) {
      device <- switch(extension, pdf = grDevices::cairo_pdf,
                       png = ragg::agg_png, svg = svglite::svglite)
      ggsave(file.path(plots_dir, paste0("Figure3.", extension)), p,
             width = 13, height = 16, units = "in", dpi = 220,
             bg = "white", device = device)
    }
    write.csv(point_data[, c("sample_id", "Patient", "cycle", "cycle_num", "Disease_type",
                             "regimen", "dataset", "PC1", "PC2", "n_missing_original",
                             "any_feature_imputed")],
              file.path(tables_dir, "Figure3_points.csv"), row.names = FALSE)
    write.csv(checks, file.path(tables_dir, "Figure3_verification_checks.csv"), row.names = FALSE)
    capture.output(sessionInfo(), file = file.path(tables_dir, "Figure3_sessionInfo.txt"))
    message("Figure 3 saved to ", file.path(plots_dir, "Figure3.pdf"))
  }
  invisible(list(plot = p, points = point_data, checks = checks,
                 coordinate_errors = coordinate_errors))
}

# Keep the plotting function available for interactive use when sourced.
if (sys.nframe() == 0L) {
  args <- commandArgs(trailingOnly = TRUE)
  project_root <- if (length(args)) normalizePath(args[1], mustWork = TRUE) else getwd()
  plots_dir <- if (length(args) > 1L) args[2] else file.path(project_root, "plots")
  build_figure3(project_root, plots_dir)
}
